const EquipmentData& GetEquipment(EquipmentCategory category,std::string_view id){
    const std::vector<EquipmentData>* data=nullptr;
    switch(category){case EquipmentCategory::Main:data=&MainEquipment();break;case EquipmentCategory::Sub:data=&SubEquipment();break;case EquipmentCategory::Special:data=&SpecialEquipment();break;}
    if(data)for(const auto& entry:*data)if(entry.id==id)return entry;
    throw std::invalid_argument("Unknown equipment ID: "+std::string(id));
}
